  final Set<int> seen = {};

  // Iterate over each divisor
  for (final num in numbers.where((n) => n > 0)) { 
    var i = num;

    while(i < limit && !seen.contains(i)){
      if(!i.isEven){
        print('Adding $i to result');
      }

      seen.add(i);
      i +=num;   
   }     
 }

 return seen.fold(0,(a,b)=> a+b); 

